/* Start:/local/templates/rs-gov/template_styles.css?17597380023701*/
.rs-orv-form .tr-row.error-field {
    border: red solid 1px;
}
.single-news__text table {
    margin-bottom: 2rem;
    display: block;
}
.single-news__text table tr {
    display: block;
    padding: 0.8rem 0;
}
.single-news__text table td {
    display: block;
}
.single-news__text table td + td {
    margin-top: 0.8rem;
}
.single-news__text .tr-row {
    font-size: 1.8rem!important;
}
.tr-row td {
    padding: 0 1.5rem;
}
.tr-row td.td-label {
    width: 100%!important;
}
.tr-row td.td-label .required {
    color: red;
}
.tr-row .ui-ctl {
    width: 100%;
    position: relative;
    margin-bottom: 0;
    min-height: 0;
}
.tr-row .calendar-icon,
.tr-row .ui-ctl-after {
    position: absolute;
    right: 0;
    top: 0;
    height: 3.6rem;
    width: 3.6rem;
    z-index: 2;
    margin: 0;
    border: none;
}
.tr-row .ui-ctl-element:not([type="checkbox"]),
.tr-row .GRAIN_LINKS_EDIT_DEFAULT-text,
.tr-row select {
    width: 100%;
    height: 3.6rem;
    padding: 0 4.6rem 0 1rem;
    display: block;
    border: 0.1rem solid gray;
    flex: none;
}
.tr-row .ui-ctl-element[type="checkbox"] {
    width: 1.8rem;
    height: 1.8rem;
}
.tr-row select {
    overflow: hidden;
    text-overflow: ellipsis;
}
div.GRAIN_LINKS_EDIT_DEFAULT-dropdown {
    font-size: 1.8rem!important;
    padding: 0;
}
div.GRAIN_LINKS_EDIT_DEFAULT-dropdown div.GRAIN_LINKS_EDIT_DEFAULT-dropdown-container {
    padding: 0;
}
div.GRAIN_LINKS_EDIT_DEFAULT-dropdown div.GRAIN_LINKS_EDIT_DEFAULT-item a {
    padding: 0.3rem 1rem;
}
.single-news__text .tr-row .GRAIN_LINKS_EDIT_DEFAULT-values-value-delete,
.single-news__text .tr-row .GRAIN_LINKS_EDIT_DEFAULT-values-multiple-value-delete {
    font-size: 2rem!important;
    text-align: center;
    display: inline-block;
    vertical-align: middle;
    width: 2rem;
    height: 2rem;
    line-height: 0.6!important;
}
.bx-bxu-thumb-thumb {
    display: flex;
    align-items: flex-start;
}
.bx-bxu-thumb-thumb:last-child {
    margin-bottom: 1rem;
}
.bx-bxu-thumb-thumb::before {
    display: block;
    flex: none;
    margin-right: 0.8rem;
}
.webform-field-item-wrap {
    display: flex;
    align-items: flex-start;
}
.upload-file-name {
    display: block;
    flex: 0 1 auto;
}
.upload-file-size {
    display: block;
    flex: none;
}
.tr-row .webform-field-upload-list del {
    display: block;
    flex: none;
    line-height: 0.8!important;
    margin-left: 0.7rem!important;
}
.webform-field-upload-list.webform-field-upload-list-single {
    margin: 0;
}
.webform-field-upload {
    border: 0.1rem solid gray;
    background: #ebebeb;
}
.webform-small-button.webform-button-replace,
.webform-small-button.webform-button-upload {
    padding-top: 0.4rem;
}
.ui-btn {
    margin-top: 1rem;
}
.label-calendar {
    position: relative;
    padding-left: 3.3rem;
}
.single-news .label-calendar .calendar-icon {
    left: auto;
    z-index: 2;
    width: 3.6rem;
}
.single-news .label-calendar span.to,
.single-news .label-calendar span.from {
    left: 0;
    top: 50%;
    transform: translateY(-50%);
}
.single-news .label-calendar {
    width: 25rem;
    display: inline-block;
    vertical-align: middle;
}
@media (min-width: 768px) {
    .single-news__text table {
        display: table;
    }
    .single-news__text table tr {
        display: table-row;
        padding: 0;
    }
    .single-news__text table td {
        display: table-cell;
        padding-top: 0.8rem;
        padding-bottom: 0.8rem;
    }
    .single-news__text table td + td {
        margin-top: 0;
    }
    .tr-row td.td-label {
        width: 30%!important;
    }
    .tr-row td {
        padding-right: 0;
    }
    .tr-row td.td-label {
        padding-right: 1.5rem;
    }
}
/* End */
